document.getElementById('stage').insertAdjacentHTML('beforeend',"<section class=\"screen dark\" id=\"s11\" data-screen=\"11\">\n  <div class=\"page-index\">11 / MATCH & BID</div>\n  <div class=\"eyebrow\">Core Product · Match</div>\n  <h1>揭榜接单：让合适的项目找到合适的人</h1>\n  <div class=\"match-layout\">\n    <div class=\"match-project\"><small>PROJECT TO MATCH</small><h2>中医药知识库建设</h2><div class=\"match-tags\"><span>RAG</span><span>知识库</span><span>中医药</span></div><div class=\"project-facts\"><div><b>30天</b><span>周期 · 示意</span></div><div><b>4项</b><span>交付物 · 示意</span></div></div><button id=\"startMatch\" class=\"match-btn\">开始匹配</button></div>\n    <div class=\"match-engine\"><div class=\"engine-core\"><span>能力匹配</span><b id=\"matchState\">READY</b></div><div class=\"engine-orbit eo1\"></div><div class=\"engine-orbit eo2\"></div><svg viewBox=\"0 0 620 520\"><path d=\"M305 260L75 105\"/><path d=\"M305 260L545 90\"/><path d=\"M305 260L80 426\"/><path d=\"M305 260L535 420\"/></svg><div class=\"criterion c1\">技能标签</div><div class=\"criterion c2\">OPC等级</div><div class=\"criterion c3\">项目经验</div><div class=\"criterion c4\">行业经验</div><div class=\"criterion c5\">时间匹配度</div></div>\n    <div class=\"candidate-list\"><div class=\"candidate active\" data-score=\"92\"><div class=\"candidate-avatar\">陈</div><div><b>陈晨</b><span>知识库 / RAG</span></div><strong>92%</strong></div><div class=\"candidate\" data-score=\"87\"><div class=\"candidate-avatar\">李</div><div><b>李明</b><span>AI应用 / 后端</span></div><strong>87%</strong></div><div class=\"candidate\" data-score=\"81\"><div class=\"candidate-avatar\">王</div><div><b>王妍</b><span>中医药 / 内容</span></div><strong>81%</strong></div><div class=\"candidate-note\">匹配分值为产品演示示意</div><div class=\"review-flow\"><span>人才申请</span><i>→</i><span>社区初筛</span><i>→</i><span>企业选择</span><i>→</i><span>专家评审</span><i>→</i><b>中榜</b></div></div>\n  </div>\n</section>\n<section class=\"screen ui-paper\" data-screen=\"12\" id=\"s12\">\n<div class=\"page-index\">12 / PROJECT DELIVERY</div>\n<div class=\"eyebrow\">Core Product · Delivery</div><h1>项目交付：真正管理“从中榜到验收”的全过程</h1>\n<div class=\"project-shell\">\n<div class=\"project-top\"><div><h2>中医药企业知识库建设项目</h2><div class=\"project-meta\"><span class=\"status\">● 执行中</span><span>项目负责人：陈晨</span><span>企业负责人：张经理</span><span>导师：王教授</span><span>周期：30天（示意）</span></div></div><div class=\"project-summary\"><div class=\"progress-ring\"><b>68%</b></div><span class=\"demo-chip\">演示示意</span></div></div>\n<div class=\"project-grid\">\n<div class=\"stage-nav\">\n<button class=\"stage-btn done\" data-stage=\"1\"><span class=\"dot\"></span>01 项目立项 ✓</button>\n<button class=\"stage-btn done\" data-stage=\"2\"><span class=\"dot\"></span>02 需求确认 ✓</button>\n<button class=\"stage-btn done\" data-stage=\"3\"><span class=\"dot\"></span>03 数据整理 ✓</button>\n<button class=\"stage-btn active\" data-stage=\"4\"><span class=\"dot\"></span>04 系统建设 ●</button>\n<button class=\"stage-btn\" data-stage=\"5\"><span class=\"dot\"></span>05 测试验收</button>\n<button class=\"stage-btn\" data-stage=\"6\"><span class=\"dot\"></span>06 项目归档</button>\n</div>\n<div class=\"workarea\">\n<div class=\"work-head\"><div><div class=\"milestone-kicker\" id=\"stageKicker\">MILESTONE 04</div><h3 id=\"stageTitle\">知识库系统建设</h3></div><div class=\"due\" id=\"stageDue\">完成时间：10月18日（示意）</div></div>\n<div class=\"task-box\"><div class=\"task-list\"><h4>当前任务</h4><div class=\"task done\"><span class=\"checkbox\">✓</span><span id=\"task1\">知识文档清洗</span></div><div class=\"task\"><span class=\"checkbox\"></span><span id=\"task2\">RAG检索调优</span></div><div class=\"task\"><span class=\"checkbox\"></span><span id=\"task3\">问答效果测试</span></div></div><div class=\"deliverable\"><h4>阶段成果</h4><div class=\"deliver-card\"><div class=\"fileico\">DOC</div><div><b id=\"deliverName\">知识库 Beta V0.8</b><small id=\"deliverMeta\">阶段交付物 · 产品演示示意</small></div><span class=\"waiting\" id=\"deliverStatus\">等待企业确认</span></div></div></div>\n<div class=\"activity\" id=\"activityText\">项目动态：已完成核心资料入库，当前进入检索调优与问答效果测试阶段。</div>\n<div class=\"process-panel\"><div class=\"process-head\"><h4>阶段协同记录</h4><span>过程演示示意</span></div><div class=\"process-line\"><time>阶段记录 01</time><i></i><b>核心资料已完成入库，进入知识结构检查。</b></div><div class=\"process-line\"><time>阶段记录 02</time><i></i><b>知识库 Beta V0.8 已提交阶段成果。</b></div><div class=\"process-line\"><time>阶段记录 03</time><i></i><b>企业侧反馈已归集，2 个问答场景等待确认。</b></div></div>\n</div>\n<aside class=\"aside\"><div class=\"aside-block\"><h4>项目成员</h4><div class=\"people\"><div class=\"mini-avatar\">陈</div><div class=\"mini-avatar\">李</div><div class=\"mini-avatar\">王</div><div class=\"mini-avatar\">导</div></div></div><div class=\"aside-block\"><h4>最新文件</h4><div class=\"listline\">知识库结构说明_v0.8.docx</div><div class=\"listline\">资料清洗记录.xlsx</div></div><div class=\"aside-block\"><h4>待处理问题</h4><div class=\"listline\">2 个问答场景需业务确认</div><div class=\"listline\">1 份资料等待补充</div></div><div class=\"aside-block\"><h4>企业反馈</h4><div class=\"listline\">“核心问答方向基本符合预期…”</div></div></aside>\n</div>\n<div class=\"project-footer\"><span>立项</span><span>计划</span><span class=\"active\">任务</span><span>文件</span><span>成果</span><span>验收</span></div>\n</div>\n<div class=\"project-quote\">接到项目不是终点，完成交付才产生真正的人才价值</div>\n</section>\n<section class=\"screen warm\" id=\"s13\" data-screen=\"13\">\n  <div class=\"page-index\">13 / EVALUATION & CERTIFICATION</div>\n  <div class=\"eyebrow\">Core Product · Certification</div>\n  <h1>评价认证：让每一次学习和项目都成为人才成长依据</h1>\n  <div class=\"cert-layout\">\n    <div class=\"evidence-sources\"><div class=\"source\"><span>学</span><div><b>课程评价</b><small>学习 · 作业 · 考试</small></div></div><div class=\"source\"><span>训</span><div><b>实训评价</b><small>项目成果 · 导师评分</small></div></div><div class=\"source\"><span>企</span><div><b>企业评价</b><small>交付质量 · 沟通 · 满意度</small></div></div><div class=\"source\"><span>项</span><div><b>项目履历</b><small>数量 · 复杂度 · 成果</small></div></div><svg viewBox=\"0 0 480 420\"><path d=\"M425 80C360 110 320 160 272 210M425 160C360 170 320 188 272 214M425 255C360 244 320 235 272 220M425 340C360 300 320 262 272 226\"/></svg></div>\n    <div class=\"level-growth\"><div class=\"level-card active\" data-cert=\"初级\"><small>LEVEL 01</small><strong>初级 OPC</strong><p>课程 + 模拟实训</p></div><i>↓</i><div class=\"level-card\" data-cert=\"中级\"><small>LEVEL 02</small><strong>中级 OPC</strong><p>完成至少 1 个真实交付项目</p></div><i>↓</i><div class=\"level-card gold\" data-cert=\"高级\"><small>LEVEL 03</small><strong>高级 OPC</strong><p>多个真实项目 + 独立商业化能力</p></div></div>\n    <div class=\"ability-orbit\"><div class=\"ability-center\"><span id=\"certLevel\">初级 OPC</span><b id=\"certScore\">成长起点</b></div><div class=\"ability-chip ac1\">专业能力</div><div class=\"ability-chip ac2\">AI能力</div><div class=\"ability-chip ac3\">项目能力</div><div class=\"ability-chip ac4\">商业能力</div><svg viewBox=\"0 0 430 430\"><circle cx=\"215\" cy=\"215\" r=\"140\"/><circle cx=\"215\" cy=\"215\" r=\"106\"/><path d=\"M215 75V355M75 215H355M116 116L314 314M314 116L116 314\"/></svg></div>\n  </div>\n</section>\n<section class=\"screen dark\" id=\"s14\" data-screen=\"14\">\n  <div class=\"page-index\">14 / COMPLIANCE</div>\n  <div class=\"eyebrow\">Compliance By Design</div>\n  <h1>医疗健康领域需要把合规能力嵌入项目全过程</h1>\n  <div class=\"compliance-layout\">\n    <div class=\"shield-core\"><svg viewBox=\"0 0 260 300\"><path d=\"M130 18L226 54V132C226 202 185 248 130 278C75 248 34 202 34 132V54L130 18Z\"/><path d=\"M89 146l28 28 58-67\"/></svg><strong>合规贯穿全流程</strong><span>需求 · 项目 · 成果 · 展示</span></div>\n    <div class=\"compliance-flow\"><article><span>01</span><h3>需求阶段</h3><p>数据来源是否合法？<br/>是否涉及医疗健康敏感内容？</p></article><i>→</i><article><span>02</span><h3>项目阶段</h3><p>数据是否授权和脱敏？<br/>AI 能力使用范围是否明确？</p></article><i>→</i><article><span>03</span><h3>成果阶段</h3><p>生成内容是否需要专家审核？<br/>知识产权归属是否清楚？</p></article><i>→</i><article><span>04</span><h3>对外展示</h3><p>宣传内容是否适合公开？<br/>成果发布是否经过审核？</p></article></div>\n    <div class=\"risk-scale\"><div class=\"risk low\"><span>低风险</span><b>常规审核</b></div><div class=\"risk mid\"><span>中风险</span><b>运营 + 专家审核</b></div><div class=\"risk high\"><span>高风险</span><b>专项评估后决定是否进入项目池</b></div></div>\n    <div class=\"compliance-note\">具体合规规则需后续结合运营制度及法律专业意见进一步确定。</div>\n  </div>\n</section>\n<section class=\"screen paper\" id=\"s15\" data-screen=\"15\">\n  <div class=\"page-index\">15 / OUTCOME & INCUBATION</div>\n  <div class=\"eyebrow\">From Delivery To Incubation</div>\n  <h1>一个项目完成之后，平台继续推动成果转化和 OPC 成长</h1>\n  <div class=\"incubation-layout\">\n    <div class=\"funnel-wrap\"><div class=\"funnel f1\"><span>真实项目</span></div><div class=\"funnel f2\"><span>优秀成果</span></div><div class=\"funnel f3\"><span>标杆案例</span></div><div class=\"funnel f4\"><span>创业项目</span></div><div class=\"funnel f5\"><span>OPC 个体 / 微型团队</span></div><div class=\"funnel f6\"><span>产业资源 / 基金储备</span></div><svg viewBox=\"0 0 500 650\"><path d=\"M250 45C313 78 335 126 329 181M328 181C318 256 283 285 257 331M257 331C221 389 205 448 235 511\"/></svg></div>\n    <div class=\"resource-wheel\"><div class=\"resource-center\"><span>OPC</span><b>孵化服务</b></div><div class=\"resource r1\">开放工位</div><div class=\"resource r2\">注册地址</div><div class=\"resource r3\">财税法务</div><div class=\"resource r4\">知识产权</div><div class=\"resource r5\">算力资源</div><div class=\"resource r6\">市场资源</div><div class=\"resource r7\">路演活动</div><div class=\"resource r8\">基金推荐</div><svg viewBox=\"0 0 600 600\"><circle cx=\"300\" cy=\"300\" r=\"165\"/><path d=\"M300 135V48M465 300h87M300 465v87M135 300H48M183 183L121 121M417 183l62-62M417 417l62 62M183 417l-62 62\"/></svg></div>\n    <div class=\"pitch-scene\"><div class=\"pitch-stage\"><span>OPC DEMO DAY</span><div class=\"presenter\"><i></i></div><div class=\"pitch-screen\"><b>AI × 中医药</b><small>创新项目路演</small></div></div><div class=\"audience\"><i></i><i></i><i></i><i></i><i></i></div></div>\n  </div>\n</section>");